// == AU平行世界生成器 (Cosmos Fleur Workshop) ==
// 版本 1.0 

(function() {
    'use strict';

    const WIDGET_ID = 'cosmos-au-generator';
    const API_STORE = 'cosmos_fleur_au_api';
    const API_MODAL_ID = 'cosmos-au-api-modal';

    const REGEX_TAG_PREFIX = '[AU-WORLD] ';
    const CUSTOM_VALUE_PREFIX = 'CUSTOM_SAVED::';

    let isWidgetVisible = true;

    const appState = {
        rawContent: '',
        generatedContent: '',
        isGenerating: false,
        selectedWorldbook: '',
    };

    // ---------- 环境检测 ----------
    let targetWindow = window;
    let targetDocument = document;
    try {
        if (window.parent && window.parent.document) {
            targetWindow = window.parent;
            targetDocument = window.parent.document;
        }
    } catch (e) {
        console.warn('[AU生成器] 无法访问父窗口，已在当前窗口运行。');
    }

    const oldInstance = targetDocument.getElementById(WIDGET_ID);
    if (oldInstance) oldInstance.remove();

    // ---------- API 配置 ----------
    function loadApiConfig() {
        try { return JSON.parse(targetWindow.localStorage.getItem(API_STORE) || 'null') || {}; }
        catch (e) { return {}; }
    }
    function saveApiConfig(cfg) {
        try { targetWindow.localStorage.setItem(API_STORE, JSON.stringify(cfg)); } catch (e) {}
    }
    function clearApiConfig() {
        try { targetWindow.localStorage.removeItem(API_STORE); } catch (e) {}
    }
    function cfgToCustomApi(cfg) {
        if (!cfg) return null;
        if (!cfg.apiurl && !cfg.model && !cfg.proxy_preset) return null;
        var ca = {};
        if (cfg.proxy_preset) ca.proxy_preset = cfg.proxy_preset;
        if (cfg.apiurl)       ca.apiurl       = cfg.apiurl;
        if (cfg.key)          ca.key          = cfg.key;
        if (cfg.model)        ca.model        = cfg.model;
        ca.source = cfg.source || 'openai';
        return ca;
    }

    // ---------- UI 骨架 ----------
    const container = targetDocument.createElement('div');
    container.id = WIDGET_ID;
    Object.assign(container.style, {
        position: 'fixed', top: '0', left: '0', width: '0', height: '0',
        zIndex: '2147483646', pointerEvents: 'none', display: 'block',
    });
    targetDocument.body.appendChild(container);

    const shadow = container.attachShadow({ mode: 'open' });

    // ---------- 样式 ----------
    const style = targetDocument.createElement('style');
    style.textContent = `
        :host { --font-main:'Segoe UI','Microsoft YaHei',sans-serif; all:initial; font-family:var(--font-main); }

        .theme-default {
            --bg-main:#1a1410;
            --bg-panel:url('https://www.transparenttextures.com/patterns/parchment.png'),linear-gradient(135deg,#fdf6e9 0%,#f5e8c8 50%,#e8d5a3 100%);
            --text-main:#3d2b1a; --text-light:#8b7355; --primary:#6b4f1d;
            --primary-light:rgba(107,79,29,0.13); --border-color:#c9a86b;
            --gold:#b8943c; --accent:#8c2f1f;
            --shadow:0 8px 32px rgba(0,0,0,.45),0 0 0 2px rgba(184,148,60,.3),inset 0 0 60px rgba(107,79,29,.12);
            --panel-font:'IM Fell English','Cormorant Garamond','Palatino Linotype',serif;
            --panel-title-font:'Uncial Antiqua','Cinzel',serif;
        }
        .theme-hp {
            --bg-main:#f0e6d6;
            --bg-panel:url('https://www.transparenttextures.com/patterns/old-paper.png'),#fdf8f0;
            --text-main:#4d4036; --text-light:#7a6a5d; --primary:#8c2323;
            --primary-light:rgba(140,35,35,.1); --border-color:#dccdbb;
            --shadow:0 5px 15px rgba(0,0,0,.15);
            --panel-font:'IM Fell English',serif;
            --panel-title-font:'Uncial Antiqua',cursive;
        }
        .theme-cyberpunk {
            --bg-main:#0a0c1a; --bg-panel:rgba(15,20,40,.9);
            --text-main:#c4f0ff; --text-light:#5f8ea3; --primary:#00f6ff;
            --primary-light:rgba(0,246,255,.1); --border-color:rgba(0,246,255,.2);
            --shadow:0 0 25px rgba(0,246,255,.2),inset 0 0 10px rgba(0,246,255,.05);
            --panel-font:'Consolas','Courier New',monospace;
            --panel-title-font:'Orbitron',sans-serif;
        }

        .float-ball {
            position:fixed; width:60px; height:60px; border-radius:50%;
            background:var(--primary-light); border:1px solid var(--border-color);
            box-shadow:var(--shadow);
            display:flex; justify-content:center; align-items:center;
            color:var(--primary); font-size:28px; line-height:1;
            font-family:'Apple Color Emoji','Segoe UI Emoji','Noto Color Emoji',sans-serif;
            cursor:grab; user-select:none; touch-action:none;
            transition:all .3s ease; pointer-events:auto; z-index:1;
        }
        .float-ball:hover { transform:scale(1.1); box-shadow:0 6px 20px rgba(0,0,0,.12); }
        .float-ball.dragging { cursor:grabbing; transition:none; }
        .hidden { transform:scale(0)!important; opacity:0!important; pointer-events:none!important; }

        .widget-panel {
            position:fixed; width:90vw; max-width:820px; height:85vh;
            background:var(--bg-panel); backdrop-filter:blur(10px);
            border:1px solid var(--border-color); border-radius:12px;
            box-shadow:var(--shadow);
            display:flex; flex-direction:column;
            color:var(--text-main); pointer-events:auto;
            transition:all .3s ease-out; font-size:14px;
            overflow:hidden; z-index:2;
        }
        .panel-header {
            padding:12px 20px; border-bottom:1px solid var(--border-color);
            display:flex; justify-content:space-between; align-items:center;
            cursor:move; user-select:none; flex-shrink:0;
        }
        .panel-title {
            font-size:22px; font-weight:bold;
            font-family:var(--panel-title-font); color:var(--primary);
            text-shadow:1px 1px 2px rgba(0,0,0,.05);
        }
        .header-actions { display:flex; align-items:center; gap:6px; }
        .icon-btn {
            font-size:18px; cursor:pointer; color:var(--text-light);
            transition:all .2s; padding:2px 6px; user-select:none; line-height:1;
        }
        .icon-btn:hover { color:var(--primary); }
        .panel-close {
            font-size:20px; cursor:pointer; color:var(--text-light);
            transition:all .2s; padding:0 4px; line-height:1;
        }
        .panel-close:hover { color:#e57373; transform:rotate(90deg); }

        .panel-body {
            flex-grow:1; padding:20px;
            display:grid; grid-template-columns:3fr 2fr; gap:20px;
            overflow-y:auto;
        }
        .left-column, .right-column { display:flex; flex-direction:column; gap:16px; }

        .control-group {
            background-color:var(--primary-light);
            border:1px solid var(--border-color); border-radius:8px;
            padding:16px; position:relative;
            box-shadow:inset 0 1px 0 rgba(255,255,255,.35),0 2px 6px rgba(0,0,0,.12);
        }
        .control-group::before {
            content:'❖'; position:absolute; top:-9px; left:16px;
            font-size:16px; color:var(--gold,var(--primary));
            pointer-events:none; z-index:3;
            text-shadow:0 0 6px rgba(184,148,60,.5);
        }
        h3 {
            font-family:var(--panel-font); font-size:16px; font-weight:bold;
            margin:0 0 12px 0; color:var(--text-main);
            border-bottom:2px solid var(--primary); padding-bottom:6px;
            display:flex; align-items:center;
        }
        h3 .step-num {
            background:var(--primary); color:white; border-radius:50%;
            width:24px; height:24px;
            display:inline-flex; justify-content:center; align-items:center;
            margin-right:10px; font-size:14px;
        }
        .helper-text { color:var(--text-light); font-size:12px; line-height:1.5; margin:0 0 8px 0; }

        .input-group { display:flex; gap:8px; margin-top:8px; flex-wrap:wrap; }

        .styled-input, .styled-select {
            flex-grow:1; padding:8px 12px;
            border:1px solid var(--border-color); border-radius:4px;
            background-color:var(--bg-panel); color:var(--text-main);
            font-size:14px; outline:none; transition:all .2s;
            box-sizing:border-box; font-family:inherit; width:100%;
        }
        .styled-input:focus, .styled-select:focus {
            border-color:var(--primary);
            box-shadow:0 0 5px var(--primary-light);
        }

        .styled-button {
            padding:8px 16px; border:1px solid var(--primary);
            background-color:var(--primary); color:white;
            border-radius:4px; cursor:pointer; font-weight:bold;
            transition:all .2s; white-space:nowrap; font-family:inherit;
        }
        .styled-button:hover:not(:disabled) { opacity:.85; box-shadow:0 2px 8px rgba(0,0,0,.1); }
        .styled-button:disabled {
            background-color:var(--border-color); border-color:var(--border-color);
            color:var(--text-light); cursor:not-allowed; opacity:.7;
        }
        .secondary-button { background:transparent; color:var(--primary); }

        textarea {
            width:100%; flex-grow:1; resize:vertical; min-height:200px;
            font-family:var(--panel-font); line-height:1.6;
            padding:8px 12px; border:1px solid var(--border-color);
            border-radius:4px; background-color:var(--bg-panel);
            color:var(--text-main); box-sizing:border-box; outline:none;
        }
        textarea.plot-input { min-height:80px; flex-grow:0; margin-top:8px; font-family:inherit; }
        textarea.custom-world-content { min-height:100px; flex-grow:0; margin-top:8px; font-family:inherit; }
        textarea:focus { border-color:var(--primary); box-shadow:0 0 5px var(--primary-light); }

        .result-container { flex-grow:1; display:flex; flex-direction:column; }
        .result-header {
            display:flex; justify-content:space-between; align-items:center;
            margin-bottom:12px; flex-wrap:wrap; gap:8px;
        }
        .result-header h3 { margin-bottom:0; flex-grow:1; }
    `;
    shadow.appendChild(style);

    const fontsLink = targetDocument.createElement('link');
    fontsLink.href = 'https://fonts.googleapis.com/css2?family=IM+Fell+English&family=LXGW+WenKai+Screen&family=Ma+Shan+Zheng&family=Orbitron:wght@700&family=Uncial+Antiqua&display=swap';
    fontsLink.rel = 'stylesheet';
    shadow.appendChild(fontsLink);

    // ---------- 悬浮球 ----------
    const floatBall = targetDocument.createElement('div');
    floatBall.className = 'float-ball theme-default';
    floatBall.innerHTML = '✒️';
    floatBall.title = 'AU平行世界生成器';
    floatBall.style.left = Math.max(12, targetWindow.innerWidth - 72) + 'px';
    floatBall.style.top = Math.max(12, Math.round(targetWindow.innerHeight * 0.62)) + 'px';
    shadow.appendChild(floatBall);

    // ---------- 面板 ----------
    const panel = targetDocument.createElement('div');
    panel.className = 'widget-panel theme-default hidden';
    panel.innerHTML = `
        <div class="panel-header">
            <div class="panel-title">AU平行世界生成器</div>
            <div class="header-actions">
                <span class="icon-btn" id="open-api-btn" title="独立 API 配置">⚙</span>
                <span class="panel-close">&times;</span>
            </div>
        </div>
        <div class="panel-body">
            <div class="left-column">
                <div class="control-group">
                    <h3><span class="step-num">1</span>读取素材</h3>
                    <p class="helper-text">自动读取当前角色卡介绍，并从下方选定的世界书中拉取内容。</p>
                    <label class="helper-text" style="display:block;margin-bottom:4px;">目标世界书（单选）</label>
                    <select id="source-worldbook" class="styled-select"></select>
                    <div class="input-group">
                        <button id="refresh-worldbooks-btn" class="styled-button secondary-button">刷新列表</button>
                        <button id="read-btn" class="styled-button">读取并合并</button>
                    </div>
                    <p class="helper-text" id="wb-status" style="margin-top:6px;"></p>
                </div>

                <div class="control-group">
                    <h3><span class="step-num">2</span>选择平行世界</h3>
                    <select id="world-select" class="styled-select">
                        <option value="龙族">龙族</option>
                        <option value="史密斯夫妇">史密斯夫妇</option>
                        <option value="哈利波特">哈利波特</option>
                        <option value="ABO">ABO</option>
                        <option value="进击的巨人">进击的巨人</option>
                        <option value="漫威">漫威</option>
                        <option value="邪恶力量">邪恶力量</option>
                        <option value="饥饿游戏">饥饿游戏</option>
                        <option value="古风">古风</option>
                        <option value="江湖">江湖</option>
                        <option value="中世纪骑士">中世纪骑士</option>
                        <option value="西幻">西幻</option>
                        <option value="赛博朋克">赛博朋克</option>
                        <option value="全息游戏">全息游戏</option>
                        <option value="乙女游戏">乙女游戏</option>
                        <option value="哨向">哨向</option>
                        <option value="美高">美高</option>
                        <option value="日高">日高</option>
                        <option value="custom">＋ 新建自定义…</option>
                    </select>

                    <div id="custom-world-area" style="display:none;margin-top:8px;">
                        <input type="text" id="custom-world-input" class="styled-input" placeholder="世界观名称（如：蒸汽朋克都市）">
                        <textarea id="custom-world-content" class="styled-input custom-world-content" placeholder="详细描述这个世界观（可留空）&#10;例如：一座悬浮于云海之上的机械都市……"></textarea>
                        <div class="input-group">
                            <button id="save-custom-world-btn" class="styled-button secondary-button">保存到正则（永久）</button>
                            <button id="delete-custom-world-btn" class="styled-button secondary-button" style="display:none;">删除此自定义</button>
                        </div>
                        <p class="helper-text" style="margin-top:6px;">保存后会以「${REGEX_TAG_PREFIX}名称」的形式写入酒馆正则扩展，<b>禁用状态</b>不会影响任何文本替换。</p>
                    </div>

                    <label class="helper-text" style="display:block;margin-top:10px;margin-bottom:4px;">额外约束（可留空）</label>
                    <textarea id="plot-direction-input" class="styled-input plot-input" placeholder="例如：只保留主角一人进入此 AU、其他角色按原作对位、性格反差再大一些……"></textarea>
                </div>

                <div class="control-group">
                    <h3><span class="step-num">3</span>生成人物 AU 设定</h3>
                    <button id="generate-btn" class="styled-button">开始生成</button>
                    <p class="helper-text" style="margin-top:6px;">只产出人物在新世界里的身份与性格改写，不预设剧情。</p>
                </div>
            </div>

            <div class="right-column">
                <div class="control-group result-container">
                    <div class="result-header">
                        <h3><span class="step-num">4</span>预览与写入</h3>
                        <div class="input-group" style="margin-top:0;">
                            <button id="export-btn" class="styled-button secondary-button" disabled>导出.txt</button>
                            <button id="write-btn" class="styled-button" disabled>写入世界书</button>
                        </div>
                    </div>
                    <textarea id="result-textarea" class="styled-input" placeholder="AI生成的结果将显示在这里..."></textarea>
                </div>
            </div>
        </div>
    `;
    shadow.appendChild(panel);

    // ---------- DOM 引用 ----------
    const closeBtn = shadow.querySelector('.panel-close');
    const header = shadow.querySelector('.panel-header');
    const openApiBtn = shadow.querySelector('#open-api-btn');
    const readBtn = shadow.querySelector('#read-btn');
    const refreshWorldbooksBtn = shadow.querySelector('#refresh-worldbooks-btn');
    const worldbookSelect = shadow.querySelector('#source-worldbook');
    const wbStatus = shadow.querySelector('#wb-status');
    const worldSelect = shadow.querySelector('#world-select');
    const plotDirectionInput = shadow.querySelector('#plot-direction-input');
    const customWorldArea = shadow.querySelector('#custom-world-area');
    const customWorldInput = shadow.querySelector('#custom-world-input');
    const customWorldContent = shadow.querySelector('#custom-world-content');
    const saveCustomWorldBtn = shadow.querySelector('#save-custom-world-btn');
    const deleteCustomWorldBtn = shadow.querySelector('#delete-custom-world-btn');
    const generateBtn = shadow.querySelector('#generate-btn');
    const resultTextarea = shadow.querySelector('#result-textarea');
    const writeBtn = shadow.querySelector('#write-btn');
    const exportBtn = shadow.querySelector('#export-btn');

    // ---------- 正则存储 ----------
    function getRegexList() {
        try {
            if (typeof getRegexScripts === 'function') {
                const arr = getRegexScripts();
                if (Array.isArray(arr)) return { list: arr, api: 'helper' };
            }
        } catch (e) {}
        try {
            if (typeof SillyTavern !== 'undefined' && SillyTavern.getContext) {
                const ctx = SillyTavern.getContext() || {};
                if (ctx.extensionSettings && Array.isArray(ctx.extensionSettings.regex)) {
                    return { list: ctx.extensionSettings.regex, api: 'context' };
                }
                if (ctx.regex_scripts && Array.isArray(ctx.regex_scripts)) {
                    return { list: ctx.regex_scripts, api: 'context' };
                }
            }
        } catch (e) {}
        try {
            if (Array.isArray(targetWindow.regex_scripts)) {
                return { list: targetWindow.regex_scripts, api: 'global' };
            }
        } catch (e) {}
        return { list: null, api: null };
    }

    function loadCustomWorldsFromRegex() {
        const out = [];
        const { list } = getRegexList();
        if (!list) return out;
        list.forEach((r) => {
            const name = String(r.scriptName || '');
            if (!name.startsWith(REGEX_TAG_PREFIX)) return;
            out.push({
                name: name.slice(REGEX_TAG_PREFIX.length),
                content: String(r.replaceString || ''),
                id: r.id,
            });
        });
        return out;
    }

    function saveCustomWorldToRegex(worldName, content) {
        if (!worldName) throw new Error('世界观名称不能为空');
        const { list, api } = getRegexList();
        if (!list) throw new Error('无法访问酒馆正则扩展，请确认已启用');

        const tag = REGEX_TAG_PREFIX + worldName;
        const placeholderKey = 'AU_WORLD_PLACEHOLDER_' + String(worldName).replace(/[^\w\u4e00-\u9fa5]/g, '_');
        const findRegex = '/(?!x)x_AU_WORLD_STORAGE_NEVER_MATCH_' + placeholderKey + '/g';

        let existing = list.find((r) => String(r.scriptName || '') === tag);
        if (existing) {
            existing.replaceString = content;
            existing.disabled = true;
        } else {
            const newScript = {
                id: (typeof crypto !== 'undefined' && crypto.randomUUID)
                    ? crypto.randomUUID()
                    : ('au-world-' + Date.now() + '-' + Math.random().toString(36).slice(2, 8)),
                scriptName: tag,
                findRegex: findRegex,
                replaceString: content,
                trimStrings: [],
                placement: [2],
                disabled: true,
                markdownOnly: false,
                promptOnly: false,
                runOnEdit: false,
                substituteRegex: 0,
                minDepth: null,
                maxDepth: null,
            };
            list.push(newScript);
        }

        try { if (typeof saveSettingsDebounced === 'function') saveSettingsDebounced(); } catch (e) {}
        try {
            if (typeof SillyTavern !== 'undefined' && SillyTavern.getContext) {
                const ctx = SillyTavern.getContext() || {};
                if (typeof ctx.saveSettingsDebounced === 'function') ctx.saveSettingsDebounced();
            }
        } catch (e) {}
        try {
            if (typeof saveRegexScript === 'function') {
                saveRegexScript(existing || list[list.length - 1]);
            }
        } catch (e) {}

        console.log('[AU生成器] 自定义世界观已保存', { tag, api });
    }

    function deleteCustomWorldFromRegex(worldName) {
        const tag = REGEX_TAG_PREFIX + worldName;
        const { list } = getRegexList();
        if (!list) return false;
        let removed = false;
        try {
            if (typeof getRegexScripts === 'function' && typeof deleteRegexScript === 'function') {
                const arr = getRegexScripts();
                const target = arr.find((r) => String(r.scriptName || '') === tag);
                if (target) { deleteRegexScript(target.id); removed = true; }
            }
        } catch (e) { console.warn('[AU生成器] helper 删除正则失败', e); }
        if (!removed) {
            const idx = list.findIndex((r) => String(r.scriptName || '') === tag);
            if (idx >= 0) { list.splice(idx, 1); removed = true; }
        }
        if (removed) {
            try { if (typeof saveSettingsDebounced === 'function') saveSettingsDebounced(); } catch (e) {}
            try {
                if (typeof SillyTavern !== 'undefined' && SillyTavern.getContext) {
                    const ctx = SillyTavern.getContext() || {};
                    if (typeof ctx.saveSettingsDebounced === 'function') ctx.saveSettingsDebounced();
                }
            } catch (e) {}
        }
        return removed;
    }

    function refreshCustomWorldOptions() {
        Array.from(worldSelect.querySelectorAll('option[data-au-custom]')).forEach((o) => o.remove());
        const customs = loadCustomWorldsFromRegex();
        const newCustomOpt = worldSelect.querySelector('option[value="custom"]');
        const parent = worldSelect;
        customs.forEach((c) => {
            const opt = targetDocument.createElement('option');
            opt.value = CUSTOM_VALUE_PREFIX + c.name;
            opt.textContent = '✦ ' + c.name;
            opt.dataset.auCustom = '1';
            opt.dataset.auContent = c.content;
            if (newCustomOpt) parent.insertBefore(opt, newCustomOpt);
            else parent.appendChild(opt);
        });
        console.log('[AU生成器] 已加载 ' + customs.length + ' 个自定义世界观');
    }

    function handleSaveCustomWorld() {
        const name = customWorldInput.value.trim();
        const content = customWorldContent.value.trim();
        if (!name) { ST.toast('请先填写世界观名称。', 'warning'); return; }
        try {
            saveCustomWorldToRegex(name, content);
            ST.toast('已保存世界观「' + name + '」到正则。', 'success');
            refreshCustomWorldOptions();
            const val = CUSTOM_VALUE_PREFIX + name;
            const opts = Array.from(worldSelect.options);
            const hit = opts.find((o) => o.value === val);
            if (hit) worldSelect.value = val;
            handleWorldSelect();
        } catch (e) {
            console.error('[AU生成器] 保存自定义失败', e);
            ST.toast('保存失败：' + (e.message || e), 'error');
        }
    }

    function handleDeleteCustomWorld() {
        const cur = worldSelect.value;
        if (!cur.startsWith(CUSTOM_VALUE_PREFIX)) {
            ST.toast('当前不是已保存的自定义世界观。', 'warning');
            return;
        }
        const name = cur.slice(CUSTOM_VALUE_PREFIX.length);
        if (!confirm('确认删除自定义世界观「' + name + '」吗？')) return;
        try {
            const ok = deleteCustomWorldFromRegex(name);
            if (ok) {
                ST.toast('已删除「' + name + '」。', 'success');
                refreshCustomWorldOptions();
                worldSelect.value = 'custom';
                handleWorldSelect();
            } else {
                ST.toast('未找到该自定义世界观。', 'warning');
            }
        } catch (e) {
            console.error('[AU生成器] 删除失败', e);
