    // ---------- 世界书读取（关键修复：多路径 + 无缓存） ----------
    function extractEntriesFromRaw(raw) {
        // 统一把各种形态的原始数据变成 [{name, content, enabled}]
        const out = [];
        const push = (e, fallbackName) => {
            if (!e) return;
            const content = e.content != null ? String(e.content) : '';
            if (!content.trim()) return;
            const enabled = e.enabled !== false && !e.disable;
            if (!enabled) return;
            out.push({
                name: e.name || e.comment || fallbackName || '条目',
                content: content
            });
        };
        if (Array.isArray(raw)) {
            raw.forEach((e, i) => push(e, '条目' + (i + 1)));
        } else if (raw && typeof raw === 'object') {
            if (raw.entries && typeof raw.entries === 'object') {
                Object.values(raw.entries).forEach((e, i) => push(e, '条目' + (i + 1)));
            } else {
                Object.values(raw).forEach((e, i) => push(e, '条目' + (i + 1)));
            }
        }
        return out;
    }

    // 关键修复：不使用 getWorldbook(name) 的单一入口，
    // 而是先拿全局 world_info，再按名字精确取；同时读前清掉旧的 worldSelect 状态
    async function readWorldbookByName(name) {
        if (!name) return { entries: [], source: 'none' };

        // 路径 1：SillyTavern 全局 world_info（最可靠，无缓存）
        try {
            const wi = targetWindow.world_info || targetWindow.worldInfo
                    || (typeof SillyTavern !== 'undefined' && SillyTavern.getContext
                        ? (SillyTavern.getContext() || {}).worldInfo
                        : null);
            if (wi && wi.worlds && wi.worlds[name]) {
                const entries = extractEntriesFromRaw(wi.worlds[name]);
                console.log('[AU生成器] 从 world_info.worlds 读取「' + name + '」，条目数：', entries.length);
                return { entries, source: 'world_info.worlds' };
            }
            if (wi && wi[name]) {
                const entries = extractEntriesFromRaw(wi[name]);
                console.log('[AU生成器] 从 world_info[name] 读取「' + name + '」，条目数：', entries.length);
                return { entries, source: 'world_info[name]' };
            }
        } catch (e) { console.warn('[AU生成器] world_info 路径失败', e); }

        // 路径 2：酒馆助手 getWorldbook —— 但传第二参数强制不走缓存（部分版本支持）
        try {
            if (typeof getWorldbook === 'function') {
                let data = null;
                try {
                    // 有些版本支持第二参数
                    data = await getWorldbook(name, true);
                } catch (e) {
                    data = null;
                }
                if (!data) {
                    data = await getWorldbook(name);
                }
                const entries = extractEntriesFromRaw(data);
                if (entries.length) {
                    console.log('[AU生成器] 从 getWorldbook 读取「' + name + '」，条目数：', entries.length);
                    return { entries, source: 'getWorldbook' };
                }
            }
        } catch (e) { console.warn('[AU生成器] getWorldbook 路径失败', e); }

        // 路径 3：SillyTavern.getContext().worldInfo 再试一次
        try {
            if (typeof SillyTavern !== 'undefined' && SillyTavern.getContext) {
                const ctx = SillyTavern.getContext() || {};
                const wi = ctx.worldInfo;
                if (wi) {
                    const world = (wi.worlds && wi.worlds[name]) || wi[name];
                    if (world) {
                        const entries = extractEntriesFromRaw(world);
                        console.log('[AU生成器] 从 ctx.worldInfo 读取「' + name + '」，条目数：', entries.length);
                        return { entries, source: 'ctx.worldInfo' };
                    }
                }
            }
        } catch (e) { console.warn('[AU生成器] ctx.worldInfo 路径失败', e); }

        return { entries: [], source: 'failed' };
    }

