    const ST = {
        isReady: () => typeof triggerSlash === 'function',
        toast: (message, severity) => {
            severity = severity || 'info';
            if (!ST.isReady()) return console.log('[Toast-' + severity + '] ' + message);
            try {
                const escaped = String(message).replace(/\|/g, '\\|');
                triggerSlash(`/echo severity=${severity} ${escaped}`);
            } catch (e) { console.log(message); }
        },
        getCharDesc: () => {
            try {
                if (typeof getCharInfo === 'function') {
                    var info = getCharInfo();
                    return Promise.resolve((info && info.description) || '');
                }
            } catch (e) {}
            try {
                if (typeof SillyTavern !== 'undefined' && SillyTavern.getContext) {
                    var ctx = SillyTavern.getContext() || {};
                    var c = ctx.characters && ctx.characters[ctx.characterId];
                    if (c && c.description) return Promise.resolve(c.description);
                }
            } catch (e) {}
            return Promise.resolve('');
        },
        getWorldbookNames: () => {
            const names = new Set();
            const addOne = (v) => { if (typeof v === 'string' && v.trim()) names.add(v.trim()); };
            const addAny = (v) => {
                if (!v) return;
                if (Array.isArray(v)) v.forEach(addOne);
                else if (typeof v === 'object') Object.keys(v).forEach(addOne);
                else addOne(v);
            };
            try { if (typeof getWorldbookNames === 'function') addAny(getWorldbookNames()); } catch (e) {}
            // 关键补充：从 world_info.worlds 直接拿键名
            try {
                const wi = targetWindow.world_info || targetWindow.worldInfo
                        || (typeof SillyTavern !== 'undefined' && SillyTavern.getContext
                            ? (SillyTavern.getContext() || {}).worldInfo
                            : null);
                if (wi && wi.worlds && typeof wi.worlds === 'object') {
                    Object.keys(wi.worlds).forEach(addOne);
                }
            } catch (e) {}
            try {
                if (typeof SillyTavern !== 'undefined' && SillyTavern.getContext) {
                    const ctx = SillyTavern.getContext() || {};
                    [ctx.worldInfoNames, ctx.world_names, ctx.worldBooks, ctx.worldbooks].forEach(addAny);
                }
            } catch (e) {}
            try { if (targetWindow.world_names) addAny(targetWindow.world_names); } catch (e) {}
            return [...names];
        },
        getWorldbookContent: async (name) => {
            const result = await readWorldbookByName(name);
            if (!result.entries.length) return '';
            return result.entries.map((e) => '【条目：' + e.name + '】\n' + e.content).join('\n\n');
        },
        listEntries: async (name) => {
            const result = await readWorldbookByName(name);
            return result.entries.map((e) => ({ name: e.name, uid: e.name }));
        },
        deleteEntry: async (wbName, uid) => {
