                    return true;
                }
            } catch (e) { console.warn('[AU生成器] 删除旧条目失败', e); }
            return false;
        },
        createEntry: async (wbName, entry) => {
            if (typeof createWorldbookEntries !== 'function') {
                throw new Error('当前环境不支持 createWorldbookEntries');
            }
            await createWorldbookEntries(wbName, [entry]);
        },
        generate: async (systemPrompt, userPrompt) => {
            if (typeof generateRaw !== 'function') {
                throw new Error('generateRaw 接口不可用，请确认已启用酒馆助手。');
            }
            const cfg = loadApiConfig();
            const ca = cfgToCustomApi(cfg);
            const req = {
