                    { role: 'system', content: String(systemPrompt || '') },
                    { role: 'user',   content: String(userPrompt || '') }
                ],
                custom_api: Object.assign({ max_tokens: 'unset' }, ca || {})
            };
            console.log('[AU生成器] 生成请求', { hasCustomApi: !!ca });
            const result = await generateRaw(req);
            if (typeof result === 'string') return result;
            return (result && (result.content || result.response || result.result)) || '';
        }
    };

