    // 生成：聚焦人物 AU 化，剥离剧情
    async function handleGenerate() {
        if (appState.isGenerating) return;

        const currentWb = String(worldbookSelect.value || '').trim();
        if (!currentWb) {
            ST.toast('请先在步骤 1 选择一本世界书。', 'warning');
            return;
        }
        // 强制重新读：只要 select 当前值 与 appState.selectedWorldbook 不一致，或内容为空，就重读
        if (!appState.rawContent.trim() || appState.selectedWorldbook !== currentWb) {
            ST.toast('素材为空或世界书已切换，正在重新读取……', 'info');
            await handleReadData();
            if (!appState.rawContent.trim()) {
                ST.toast('读取素材失败，请手动点击「读取并合并」。', 'error');
                return;
