            const opt = worldSelect.selectedOptions[0];
            targetWorld = targetWorld.slice(CUSTOM_VALUE_PREFIX.length);
            customWorldDesc = (opt && opt.dataset.auContent) || '';
        } else if (targetWorld === 'custom') {
            targetWorld = customWorldInput.value.trim();
            customWorldDesc = customWorldContent.value.trim();
            if (!targetWorld) {
                ST.toast('请输入自定义世界观名称！', 'warning');
                return;
