        const extraConstraint = plotDirectionInput.value.trim();

        const customWorldBlock = customWorldDesc
            ? '\n\n【目标世界观详述】\n' + customWorldDesc
            : '';

        const extraBlock = extraConstraint
            ? '\n\n【额外约束】\n' + extraConstraint
            : '';

        // 新提示词：不写剧情，只做人物 AU 化
