    // 写入选定的世界书
    async function handleWrite() {
        const content = resultTextarea.value.trim();
        if (!content) {
            ST.toast('没有可写入的内容！', 'warning');
            return;
        }

        const wbName = worldbookSelect.value;
        if (!wbName) {
            ST.toast('请先在步骤 1 选择一本世界书，再写入。', 'warning');
            return;
        }

        const worldVal = worldSelect.value.startsWith(CUSTOM_VALUE_PREFIX)
            ? worldSelect.value.slice(CUSTOM_VALUE_PREFIX.length)
            : worldSelect.value;
        const defaultName = 'AU衍生_' + worldVal + '_' + new Date().toLocaleString('zh-CN').replace(/[/: ]/g, '-');
        const entryName = prompt('写入世界书「' + wbName + '」\n请输入条目名（留空用默认名）：', defaultName);
        if (entryName === null) return;
        const finalName = (entryName || '').trim() || defaultName;

        try {
            ST.toast('正在写入……', 'info');

            const existing = await ST.listEntries(wbName);
            const dup = existing.filter((e) => e.name === finalName);
            for (const e of dup) {
                await ST.deleteEntry(wbName, e.uid);
            }

            await ST.createEntry(wbName, {
                name: finalName,
                enabled: true,
                strategy: {
                    type: 'selective',
                    keys: ['AU', worldVal],
                    keys_secondary: { logic: 'and_any', keys: [] },
                    scan_depth: 'same_as_global'
                },
                position: {
                    type: 'before_character_definition',
                    order: 100,
                    role: 'system',
                    depth: 4
                },
                content: content
            });

            ST.toast('已写入世界书「' + wbName + '」\n条目名：' + finalName, 'success');
        } catch (e) {
            console.error('[AU生成器] 写入失败', e);
            ST.toast('写入失败：' + (e.message || e), 'error');
        }
    }

    function handleExport() {
        const content = resultTextarea.value;
        if (!content) return;
        const blob = new Blob([content], { type: 'text/plain;charset=utf-8' });
        const a = targetDocument.createElement('a');
        a.href = URL.createObjectURL(blob);
        a.download = 'AU设定_' + worldSelect.value + '_' + Date.now() + '.txt';
        a.click();
        URL.revokeObjectURL(a.href);
    }

    // ---------- 事件绑定 ----------
    closeBtn.addEventListener('click', closePanel);
