    // ---------- 拖拽 ----------
    const makeDraggable = (element, handle, isBall) => {
        const DRAG_THRESHOLD = 4;
        let isDragging = false;
        let didDrag = false;
        let startX = 0, startY = 0, baseLeft = 0, baseTop = 0;
        let reqFrame = null;

        const clampPos = (x, y) => {
            const w = element.offsetWidth || 60;
            const h = element.offsetHeight || 60;
            return {
                x: Math.max(0, Math.min(x, targetWindow.innerWidth - w)),
                y: Math.max(0, Math.min(y, targetWindow.innerHeight - h))
            };
        };

        const applyPos = (x, y) => {
            const p = clampPos(x, y);
            element.style.left = p.x + 'px';
            element.style.top = p.y + 'px';
        };

        const onDown = (e) => {
            if (e.button !== undefined && e.button !== 0) return;
            const rect = element.getBoundingClientRect();
            startX = e.clientX !== undefined ? e.clientX : (e.touches && e.touches[0].clientX);
            startY = e.clientY !== undefined ? e.clientY : (e.touches && e.touches[0].clientY);
            baseLeft = rect.left;
            baseTop = rect.top;
            isDragging = true;
            didDrag = false;
            element.classList.add('dragging');
            targetDocument.addEventListener('mousemove', onMove, { passive: false });
            targetDocument.addEventListener('mouseup', onUp);
            targetDocument.addEventListener('touchmove', onTouchMove, { passive: false });
            targetDocument.addEventListener('touchend', onUp);
            e.stopPropagation();
        };

        const onMove = (e) => {
            if (!isDragging) return;
            e.preventDefault();
            if (!didDrag && Math.hypot(e.clientX - startX, e.clientY - startY) < DRAG_THRESHOLD) return;
            didDrag = true;
            if (reqFrame) cancelAnimationFrame(reqFrame);
            reqFrame = requestAnimationFrame(() => {
                applyPos(baseLeft + (e.clientX - startX), baseTop + (e.clientY - startY));
            });
        };

        const onTouchMove = (e) => {
            if (!isDragging || !e.touches.length) return;
            e.preventDefault();
            const t = e.touches[0];
            if (!didDrag && Math.hypot(t.clientX - startX, t.clientY - startY) < DRAG_THRESHOLD) return;
            didDrag = true;
            if (reqFrame) cancelAnimationFrame(reqFrame);
            reqFrame = requestAnimationFrame(() => {
                applyPos(baseLeft + (t.clientX - startX), baseTop + (t.clientY - startY));
            });
        };

        const onUp = () => {
            targetDocument.removeEventListener('mousemove', onMove);
            targetDocument.removeEventListener('mouseup', onUp);
            targetDocument.removeEventListener('touchmove', onTouchMove);
            targetDocument.removeEventListener('touchend', onUp);
            if (reqFrame) cancelAnimationFrame(reqFrame);
            if (!isDragging) return;

            isDragging = false;
            element.classList.remove('dragging');

            if (isBall && didDrag) {
                const rect = element.getBoundingClientRect();
                const goLeft = rect.left + rect.width / 2 < targetWindow.innerWidth / 2;
                applyPos(
                    goLeft ? 12 : targetWindow.innerWidth - rect.width - 12,
                    rect.top
                );
            }
            if (isBall && !didDrag) openPanel();
        };

        handle.addEventListener('mousedown', onDown);
        handle.addEventListener('touchstart', onDown, { passive: true });
    };

    makeDraggable(panel, header, false);
    makeDraggable(floatBall, floatBall, true);

    // ---------- 脚本按钮 ----------
    if (typeof eventOn === 'function' && typeof getButtonEvent === 'function') {
        eventOn(getButtonEvent('开启/关闭AU生成器'), toggleWidget);
    }

    // ---------- 初始化 ----------
    loadWorldbookOptions();
    refreshCustomWorldOptions();
    applyVisibility(true);

    floatBall.classList.remove('hidden');
    panel.classList.add('hidden');

    $(window).on('pagehide', () => {
        const instance = targetDocument.getElementById(WIDGET_ID);
        if (instance) instance.remove();
        const modal = targetDocument.getElementById(API_MODAL_ID);
        if (modal) modal.remove();
    });

    console.log('[AU生成器] 已加载 v1.5');
})();
